import ru.bccontrol.sedonastudio.model.*;import ru.bccontrol.sedonastudio.storage.*;import ru.bccontrol.sedonastudio.protocol.*;import java.util.*;import java.nio.file.*;import java.io.*;
public class CoreTests {
 static int passed;static void check(boolean value,String why){if(!value)throw new AssertionError(why);passed++;}static void fails(Runnable call,String why){try{call.run();throw new AssertionError("Accepted "+why);}catch(IllegalArgumentException expected){passed++;}}
 public static void main(String[] args)throws Exception{List<Project.Node> types=Catalog.bundled();check(types.size()==9,"Bundled catalog");Project p=new Project();Project.Node a=types.get(0).copy(),b=types.get(2).copy();a.id="a";a.name="source";a.x=40;a.y=50;b.id="b";b.name="sum";b.x=400;b.y=90;p.nodes.put(a.id,a);p.nodes.put(b.id,b);p.parts.add(a.kitPart);p.parts.add(b.kitPart);p.connect("a","out","b","in1");check(p.validate().isEmpty(),"Valid graph");fails(()->p.connect("a","out","b","in1"),"two inputs");fails(()->p.connect("b","out","a","missing"),"missing port");Project.Node bool=types.get(1).copy();bool.id="bool";bool.name="boolean";p.nodes.put(bool.id,bool);fails(()->p.connect("bool","out","b","in2"),"type mismatch");fails(()->p.connect("a","out","b","out"),"readonly target");
 History h=new History();h.reset(p.copy());h.edit(v->v.nodes.get("a").x=300);check(p.nodes.get("a").x==40,"No aliasing");check(h.undo()&&h.get().nodes.get("a").x==40,"Undo");check(h.redo()&&h.get().nodes.get("a").x==300,"Redo");h.undo();h.edit(v->v.nodes.get("a").x=100);check(!h.redo(),"Redo branch cleared");fails(()->h.edit(v->v.nodes.get("a").name="../bad"),"name traversal");check(h.get().nodes.get("a").name.equals("source"),"Failed edit atomic");h.edit(v->v.remove("a"));check(h.get().wires.isEmpty(),"Delete removes wires");h.undo();check(h.get().wires.size()==1,"Undo restores wires");Project cyclic=p.copy();cyclic.nodes.get("a").parent="b";cyclic.nodes.get("b").parent="a";check(!cyclic.validate().isEmpty(),"Folder cycle");Project numeric=p.copy();numeric.nodes.get("a").x=Double.NaN;check(!numeric.validate().isEmpty(),"Invalid coordinates");
 String json=ProjectStore.encode(p);Project copy=ProjectStore.decode(json);check(ProjectStore.encode(copy).equals(json),"JSON roundtrip");fails(()->ProjectStore.decode(json.replace("sedona-studio","wrong-format")),"wrong format");fails(()->Json.object("{\"a\":1,\"a\":2}"),"duplicate JSON key");Path output=Paths.get(args[0]);Files.createDirectories(output);Path file=output.resolve("roundtrip.sedona.json");ProjectStore.save(p,file);p.name="Second";ProjectStore.save(p,file);check(Files.exists(output.resolve("roundtrip.sedona.json.bak")),"Previous backup");check(ProjectStore.load(file).name.equals("Second"),"Atomic save");check(ScalarValues.sensitive("password")&&ScalarValues.sensitive("cred")&&!ScalarValues.sensitive("out"),"Secret filter");
 try{ManifestArchive.importManifests("<!DOCTYPE x><kitManifest/>".getBytes("UTF-8"));throw new AssertionError("Accepted DTD");}catch(IOException expected){passed++;}
 check(ScalarValues.validateLiteral("sys::long","9007199254740993").equals("9007199254740993"),"64-bit precision");fails(()->ScalarValues.validateLiteral("sys::long","9223372036854775808"),"long overflow");fails(()->ScalarValues.validateLiteral("sys::byte","256"),"byte overflow");fails(()->ScalarValues.validateLiteral("sys::short","-1"),"unsigned short");fails(()->ScalarValues.validateLiteral("sys::float","1e100"),"float overflow");fails(()->ScalarValues.validateLiteral("sys::double","NaN"),"non-finite value");fails(()->ScalarValues.validateLiteral("sys::bool","1"),"Boolean coercion");fails(()->ProjectStore.decode(json.replace("\"version\":1","\"version\":1.5")),"fractional format version");check(SecretFields.matches("apiToken")&&SecretFields.matches("pwd"),"Secret aliases");
 Project secretProject=p.copy();secretProject.nodes.get("a").values.put("password","do-not-export");check(!ProjectStore.encode(secretProject).contains("do-not-export"),"Export never contains secret field values");
 check(ScalarValues.validateText(" in1*2+sqrt(in2) ",64).equals(" in1*2+sqrt(in2) "),"Formula preserves spaces");
 fails(()->ScalarValues.validateText("abcd",4),"Text reserves terminator");
 fails(()->ScalarValues.validateText("a\0b",20),"Text rejects embedded terminator");
 fails(()->ScalarValues.validateText("формула",64),"Text rejects non-ASCII");
 Project textProject=p.copy();Project.Port textPort=textProject.nodes.get("a").ports.get(0);textPort.asStr=true;textPort.textMax=64;
 Project restoredText=ProjectStore.decode(ProjectStore.encode(textProject));check(restoredText.nodes.get("a").ports.get(0).asStr&&restoredText.nodes.get("a").ports.get(0).textMax==64,"Text schema persistence");
 check(textProject.copy().nodes.get("a").ports.get(0).asStr,"Text schema history copy");
 System.out.println("PASS core "+passed+" checks: isolated history, links, validation, JSON, atomic persistence, secrets and manifest parser");}
}
